const extra=document.createElement('style');extra.textContent=`header{background:linear-gradient(120deg,#1e382e,#111e1a)}.challenge{display:grid;grid-template-columns:1.5fr 1fr;gap:20px;background:linear-gradient(120deg,#284633,#1b2d25);border:1px solid #537b59;border-radius:12px;padding:22px;margin-bottom:20px}.next{font-size:21px;font-weight:650;margin:10px 0}.steps{display:flex;gap:8px;margin-top:15px}.step{flex:1;border-top:3px solid #466350;padding-top:8px;font-size:12px;color:#a4b7aa}.step.on{border-color:#b6f59c;color:#d8fbc7}.meter{height:6px;background:#172b21;border-radius:9px;margin-top:12px;overflow:hidden}.meter span{display:block;height:100%;background:#c5e7a1;transition:width .2s}.points{font-size:34px;color:#ddf6bd;font-weight:700}.keybutton{background:#b8e493!important;color:#14251b!important;font-weight:700;border-color:#c8efaa!important;box-shadow:0 0 22px #b8e49318}.warning{color:#ffcb87}.modebar{display:flex;gap:9px;margin-bottom:18px;align-items:center;flex-wrap:wrap}.trainlabel{font-size:12px}.end{position:fixed;inset:0;background:#07100de8;z-index:10;display:grid;place-items:center;padding:25px}.endcard{max-width:480px;background:#20362a;border:1px solid #6f946b;border-radius:18px;padding:35px;text-align:center}.endcard h2{font-size:29px}.platformPick{cursor:pointer}.platformPick:hover{stroke:#ecffc3;stroke-width:14}@media(max-width:700px){.challenge{grid-template-columns:1fr}.next{font-size:18px}.points{font-size:27px}}`;document.head.append(extra);
let play={mode:'practice',points:0,combo:0,handled:0,deadline:45,ended:false,best:0};try{play.best=Number(localStorage.getItem('aoba-best'))||0}catch{}
const box=document.createElement('div');box.innerHTML=`<div class="modebar"><button id="practice" class="active">練習運転</button><button id="challenge">3分チャレンジ</button><span class="muted" id="modehint">時間制限なし。鎖錠の仕組みをじっくり確認できます。</span></div><section class="challenge"><div><small>運転ナビゲーション</small><div class="next" id="next"></div><div id="tip" class="muted"></div><div class="steps"><span class="step" id="step0">01 進路設定</span><span class="step" id="step1">02 入場・到着</span><span class="step" id="step2">03 出発・解錠</span></div></div><div><small id="scorelabel">運転スコア</small><div class="points"><span id="points">0</span> <small style="font-size:13px">pt</small></div><div id="bonus"></div><div class="meter"><span id="meter"></span></div><small id="remaining"></small></div></section>`;document.querySelector('main').prepend(box);
const oldRender=render,oldTick=tick,oldReset=reset,oldSet=setRoute;
function restart(mode){play={...play,mode,points:0,combo:0,handled:0,deadline:45,ended:false};document.querySelector('.end')?.remove();oldReset();$('dir').value='in';$('dest').value='2';render()}
reset=()=>restart(play.mode);
setRoute=()=>{if(play.ended)return;oldSet()};$('set').onclick=setRoute;
function finish(){play.ended=true;s.pause=true;play.best=Math.max(play.best,play.points);try{localStorage.setItem('aoba-best',play.best)}catch{}let el=document.createElement('div');el.className='end';el.innerHTML=`<div class="endcard"><small>勤務終了 / SHIFT COMPLETE</small><h2>${play.points>=700?'見事な運転取扱！':play.points>=300?'指令員、お疲れさま！':'次の勤務で腕試し！'}</h2><div class="points">${play.points} pt</div><p>指定番線への到着 ${s.score} 本<br>自己ベスト ${play.best} pt</p><p class="muted">信号停止後の接近鎖錠と、通過後の区分解錠が攻略のポイントです。</p><button id="again" class="keybutton">もう一度チャレンジ</button> <button id="back">練習する</button></div>`;document.body.append(el);$('again').onclick=()=>restart('challenge');$('back').onclick=()=>restart('practice')}
tick=dt=>{if(play.ended)return;let prior=s.score,loc=s.train?.loc,n=s.train?.n;oldTick(dt);if(s.score>prior){play.combo++;let bonus=Math.max(0,Math.round((play.deadline-s.time)*2));let earned=100+bonus+Math.min(5,play.combo)*20;play.points+=earned;log(`定着 +${earned}pt ／ ${play.combo}連続成功`);$('dir').value='out';$('dest').value=String(s.train.loc.slice(1));}else if(loc==='T'&&s.train?.loc?.startsWith('P')&&s.r?.stage===1&&s.r.n!==s.goal){play.combo=0;}if(!s.train&&n){play.handled++;play.deadline=s.time+45;$('dir').value='in';$('dest').value=String(s.goal);}if(play.mode==='challenge'&&s.time>=180)finish();render()};
render=()=>{oldRender();if(!$('next'))return;const r=s.r,t=s.train;let step=0,next='',tip='';if(r?.cancel!==null&&r?.cancel!==undefined){next=`接近鎖錠の解錠待ち · ${Math.ceil(r.cancel)}秒`;tip='信号は停止中。解錠後に進路を設定し直せます。'}else if(r){step=r.d==='out'?2:1;next=r.d==='out'?'出発列車の通過を監視':r.stage===1?'到着確認・進路解錠待ち':'入場列車の通過を監視';tip=r.throatReleased?'後尾がのど部を通過。転てつ器区分は解錠済みです。':'鎖錠中の転てつ器は転換できません。'}else if(!t){next='次の列車を西方に呼ぼう';tip='「西方に列車を呼ぶ」を押すと次の運転が始まります。'}else if(t.loc==='A'){next=`${s.goal}番線への入場進路を設定`;tip='方向「入場」と指定番線を選び、進路設定を押します。番線の線路をクリックしても選べます。'}else{step=2;next=`${t.loc.slice(1)}番線から西方へ出発`;tip='方向「出発」と在線番線を選んで、進路を設定します。'}$('next').textContent=next;$('tip').textContent=tip;for(let i=0;i<3;i++)$('step'+i).className='step'+(step===i?' on':'');$('points').textContent=play.points;$('bonus').textContent=`${play.combo} 連続成功　／　自己ベスト ${play.best} pt`;$('remaining').textContent=play.mode==='challenge'?`勤務終了まで ${Math.max(0,Math.ceil(180-s.time))}秒 · 定着ボーナスあと ${Math.max(0,Math.ceil(play.deadline-s.time))}秒`:'指定番線への到着で100pt＋定着・連続ボーナス';$('meter').style.width=(play.mode==='challenge'?Math.max(0,(180-s.time)/180)*100:100)+'%';$('practice').className=play.mode==='practice'?'active':'';$('challenge').className=play.mode==='challenge'?'active':'';$('modehint').textContent=play.mode==='practice'?'時間制限なし。鎖錠の仕組みをじっくり確認できます。':'3分間で高得点へ。停止中は時計も止まります。';$('set').classList.toggle('keybutton',!!t&&!r);$('spawn').classList.toggle('keybutton',!t&&!r);$('set').disabled=!!r||play.ended;$('spawn').disabled=!!t||play.ended;$('cancel').disabled=!r||play.ended;$('pause').disabled=play.ended;$('speed').disabled=play.mode==='challenge';$('sig').setAttribute('fill',r?.green&&r.d==='in'?'#8dff9b':'#ff655d');for(let i=1;i<=3;i++)$('out'+i)?.setAttribute('fill',r?.green&&r.d==='out'&&r.n===i?'#8dff9b':'#ff655d')};
for(let i=1;i<=3;i++){let rail=$('bP'+i);rail.classList.add('platformPick');rail.style.cursor='pointer';rail.onclick=()=>{$('dest').value=String(i);s.note=`${i}番線を選択。方向を確認して「進路設定」を押してください。`;render()};let circle=document.createElementNS('http://www.w3.org/2000/svg','circle');circle.id='out'+i;circle.setAttribute('cx','700');circle.setAttribute('cy',String([0,60,160,260][i]));circle.setAttribute('r','9');circle.setAttribute('class','signal');rail.parentNode.append(circle)}
$('practice').onclick=()=>{if(s.time<1||confirm('練習運転を最初から始めますか？'))restart('practice')};$('challenge').onclick=()=>{if(s.time<1||confirm('3分チャレンジを最初から始めますか？'))restart('challenge')};render();


